from __future__ import annotations
from typing import Literal
from pydantic import BaseModel, ConfigDict, Field

Discipline = Literal['architecture','structure','hydraulic','fire']

class ValidationModel(BaseModel):
    model_config=ConfigDict(extra='forbid')

class ValidationThresholds(ValidationModel):
    min_import_coverage: float = Field(default=.85, ge=0, le=1)
    min_recognition_rate: float = Field(default=.45, ge=0, le=1)
    min_mean_confidence: float = Field(default=.70, ge=0, le=1)
    max_unsupported_rate: float = Field(default=.15, ge=0, le=1)
    require_ifc_export: bool = True
    require_network_for_mep: bool = True

class ValidationCase(ValidationModel):
    name: str
    discipline: Discipline
    source_path: str
    evidence_kind: Literal['fixture','public_sample','real_project'] = 'fixture'
    project_name: str | None = None
    expected_element_counts: dict[str,int] = Field(default_factory=dict)
    thresholds: ValidationThresholds = Field(default_factory=ValidationThresholds)
    resolve_xrefs: bool = True

class DisciplineValidationReport(ValidationModel):
    case_name: str
    discipline: Discipline
    source_path: str
    evidence_kind: Literal['fixture','public_sample','real_project']
    provider: str
    dwg_version: str | None = None
    import_coverage: float
    unsupported_rate: float
    converted_entities: int
    unsupported_entities: int
    canonical_entities: int
    recognized_source_entities: int
    eligible_source_entities: int | None = None
    ignored_source_entities: int = 0
    unclassified_eligible_count: int = 0
    unclassified_by_layer: dict[str,int] = Field(default_factory=dict)
    unmapped_by_layer: dict[str,int] = Field(default_factory=dict)
    layer_role_counts: dict[str,int] = Field(default_factory=dict)
    context_by_layer: dict[str,int] = Field(default_factory=dict)
    unknown_nonannotation_count: int = 0
    catalog_advisory_count: int = 0
    catalog_assigned_count: int = 0
    recognition_rate: float
    project_elements: int
    relevant_elements: int
    element_counts: dict[str,int] = Field(default_factory=dict)
    relevant_element_counts: dict[str,int] = Field(default_factory=dict)
    expected_element_counts: dict[str,int] = Field(default_factory=dict)
    expected_count_coverage: float | None = None
    mean_confidence: float
    low_confidence_count: int
    review_pending_count: int
    network_count: int = 0
    xref_missing: list[str] = Field(default_factory=list)
    ifc_exported: bool = False
    ifc_sanity_passed: bool = False
    warnings: list[str] = Field(default_factory=list)
    errors: list[str] = Field(default_factory=list)
    passed: bool
    failed_criteria: list[str] = Field(default_factory=list)

class FederatedElementRef(ValidationModel):
    discipline: Discipline
    project_id: str
    element_id: str
    element_type: str
    storey_id: str | None = None
    bbox: tuple[float,float,float,float,float,float] | None = None

class CrossDisciplineClashCandidate(ValidationModel):
    left: FederatedElementRef
    right: FederatedElementRef
    overlap_volume: float = 0.0

class FederatedValidationSnapshot(ValidationModel):
    disciplines: list[Discipline]
    project_ids: dict[Discipline,str]
    element_counts: dict[Discipline,int]
    total_elements: int
    issue_targets: dict[Discipline,list[str]] = Field(default_factory=dict)
    network_counts: dict[Discipline,int] = Field(default_factory=dict)
    id_collisions: list[str] = Field(default_factory=list)
    cross_discipline_candidates: list[CrossDisciplineClashCandidate] = Field(default_factory=list)
    passed: bool
    warnings: list[str] = Field(default_factory=list)

class RealDWGValidationBatch(ValidationModel):
    reports: list[DisciplineValidationReport]
    federation: FederatedValidationSnapshot | None = None
    all_passed: bool
    production_evidence_eligible: bool
    blockers: list[str] = Field(default_factory=list)
